    product('dongshi','material','fine-shell-dongshi','羙貝（東始水文）','Fine shells (Dongshi water account)','其中多羙貝','Fine shells are abundant in the water account.','羙贝按水文物产录名，不添贝内生物形貌或珍珠。')
    zi=form('dongshi','zi-dongshi','茈魚（東始）','Zi fish (Dongshi)','多茈魚其状如鮒一首而十身其臭如蘪蕪食之不䊧','茈鱼鲋状一首十身；一首、十个独立鱼躯与尾端逐数，头身连接排布、鳍尾鳞纹与配色为艺术解释。蘪蕪比气味不增花草器官，食不䊧为古述。','Zi fish resemble crucian carp with one head and ten bodies, smell like miwu and are said to prevent flatulence when eaten.','One head and ten substantial fish trunks are mandatory; arrangement, fin/tail/scale details and colors are artistic. The scent adds no plant organs.',commentary='孚謂反止失氣也',en_commentary='Guo Pu supplies the pronunciation and explains the ancient eating claim as preventing passing gas.',water=True);pair(ci,zi)
    shigao=water('nvzheng','shigao','石膏水（女烝）','Shigao water (Nvzheng)','石膏水出焉而西注于鬲水','Shigao water rises here and flows west into Ge water.','完整水名石膏水，不拆为矿物。');ge=water('nvzheng','ge-water','鬲水','Ge water','西注于鬲水','It flows west into Ge water.','鬲水为石膏水受水体。');pair(shigao,ge)
    bo=form('nvzheng','bo-nvzheng','薄魚（女烝）','Bo fish (Nvzheng)','其中多薄魚其状如鱣魚而一目其音如歐見則天下大旱','薄鱼鱣鱼状一目，音如呕。图中单目中置及概括鱼体吻鳍尾、色彩与游姿为解释，不以普通侧身鱼一只可见眼冒充一目。旱兆为古述。','Bo fish resemble Zhan fish with one eye and sound like retching; their appearance is said to bring great drought.','Exactly one eye is mandatory; its central placement, generalized fish details, colors and pose are artistic.',commentary='如人嘔吐聲也',en_commentary='Guo Pu compares the sound with human retching.',water=True);pair(shigao,bo)
    shi=water('qinshan','shi-qinshan','師水（欽山）','Shi water (Qin)','師水出焉而北流注于皐澤','The Shi rises here and flows north into Gao marsh.','師水与食水原字不同，分别建索引。');gao=water('qinshan','gao-marsh','皐澤（師水受水体）','Gao marsh (Shi recipient)','北流注于皐澤','It flows north into Gao marsh.','師水受水体，不与其他篇同音泽强并。');pair(shi,gao)
