    form('qinshan','dangkang-qin','当康','Dangkang (Qin)','有獸焉其狀如豚而有牙其名曰當康其鳴自叫見則天下大穰','當康豚状有牙、鸣自叫，丰穰兆为古述。保留稳定ID及经复核旧图；四足、牙数、背毛配色及站姿为艺术解释，不把夸张牙数当原文。','Dangkang resembles a pig with tusks and calls its name; its appearance is said to bring great abundance.','The stable ID and reviewed old image remain; four feet, tusk count, coat colors and stance are artistic.',legacy_id='beast-dangkang',reuse_artwork='beasts/beast-dangkang.webp')
    zitong=water('zitong','zitong','子桐之水','Zitong water','子桐之水出焉而西流注于餘如之澤','Zitong water rises here and flows west into Yuru marsh.','子桐水西注餘如泽，山名水名分卡。');yuru=water('zitong','yuru-marsh','餘如之澤','Yuru marsh','西流注于餘如之澤','It flows west into Yuru marsh.','子桐水受水体。');pair(zitong,yuru)
    hua=form('zitong','hua-zitong','䱻魚（子桐）','Hua fish (Zitong)','其中多䱻魚其状如魚而鳥翼出入有光其音如鴛鴦見則天下大旱','䱻鱼鱼状鸟翼、出入有光；图中两羽翼数位、普通鱼首鳍尾、配色亮纹为艺术解释。鸳鸯仅比音，不添鸭首；旱兆为古述。','Hua fish are fish-shaped with bird wings, shine on entering and emerging and sound like mandarin ducks; their appearance is said to bring great drought.','Wing pair and placement, ordinary fish details, colors and light incisions are artistic, without a duck head or halo.',commentary='音滑',en_commentary='Guo Pu gives hua pronunciation.',water=True);pair(zitong,hua)
    heyu=form('yanshan','heyu-yanshan','合窳','Heyu (Yan)','有獸焉其状如彘而人面黄身而赤尾其名曰合窳其音如嬰兒是獸也食人亦食蟲蛇見則天下大水','合窳彘状人面黄身赤尾，源文四项形貌均核；人面细节、四裂蹄、耳形尾卷与站姿为艺术解释。婴儿音、食人食虫蛇与洪水兆为古述。稳定ID沿用，旧误配鱼翼图保留文件但不再用于本卡。','Heyu resembles a pig with a human face, yellow body and red tail, sounds like an infant, is described as eating people, insects and snakes, and is said to bring great flood.','Human facial details, four cloven hooves, ears, tail curl and stance are artistic. The stable ID remains while an incorrectly assigned winged-fish image is replaced.',commentary='音庾',en_commentary='Guo Pu gives yu pronunciation.',legacy_id='beast-heyu')
    for key,n,en,q,eq in [('insects-yanshan','蟲（合窳食性泛称）','Insects (Heyu food account)','亦食蟲蛇','It is also described as eating insects and snakes.'),('snakes-yanshan','蛇（合窳食性泛称）','Snakes (Heyu food account)','亦食蟲蛇','It is also described as eating insects and snakes.')]:
        target=unknown('yanshan',key,n,en,q,eq,'食性记述中的泛称，不作新神兽或具体物种造型。',kind='animal');pair(heyu,target)
    product('taishan-range4','plant','zhenwood-tai4','楨木（太山）','Zhen wood (fourth-range Tai)','上多金玉楨木','Gold, jade and zhen wood are abundant above.','楨木郭注女楨也、葉冬不凋；仅记古植物说明，不强定现代栽培种。');out[-1].update(commentary='女楨也葉冬不凋',en_commentary='Guo Pu identifies the wood as nuzhen and says its leaves do not wither in winter.')
    fei=form('taishan-range4','fei-taishan','蜚','Fei (fourth-range Tai)','有獸焉其状如牛而白首一目而蛇尾其名曰蜚行水則竭行草則死見則天下大疫','蜚牛状白首、一目蛇尾；图中四裂蹄、双牛角、单目中置、蛇样尾鳞和深色躯为解释。蛇尾端不加蛇首或额外眼，稳定ID沿用。水竭草死疫兆与跨行铭文为古述。','Fei resembles an ox with a white head, one eye and a snake tail; its passage is said to dry waters, kill vegetation and bring epidemics.','Four cloven hooves, two horns, central eye placement, tail-scale detail and dark body color are artistic. No serpent head or extra eye is added to the tail; the stable ID remains.',commentary='音如翡翠之翡；言其體含災氣也其銘曰蜚之；為名體似無害所經枯竭甚於鴆厲萬物斯懼思爾遐逝',en_commentary='Guo Pu supplies fei pronunciation, explains the disaster-bearing body and quotes an inscription continuing across units 136–137. It describes Fei, not Gou water.',legacy_id='beast-fei')
    gou=water('taishan-range4','gou-tai4','鈎水（太山）','Gou water (fourth-range Tai)','鈎水出焉而北流注于勞水','The Gou rises here and flows north into the Lao.','鈎水北注勞水，跨行蜚铭文不归水名。');lao=water('taishan-range4','lao-water','勞水','Lao water','北流注于勞水','It flows north into the Lao.','鈎水受水体。');pair(gou,lao)
